-- ProjectRoom Durable Object (SQLite). One instance per project.
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);           -- revision, timeline_revision, workspace_id, title
CREATE TABLE canvases (id TEXT PRIMARY KEY, title TEXT NOT NULL, viewport TEXT);
CREATE TABLE nodes (id TEXT PRIMARY KEY, canvas_id TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('text','script','image','video','audio','asset','render')), title TEXT NOT NULL, params TEXT NOT NULL DEFAULT '{}', x REAL NOT NULL, y REAL NOT NULL, group_id TEXT, active_version_id TEXT, status TEXT NOT NULL DEFAULT 'idle', created_by TEXT NOT NULL, updated_at INTEGER NOT NULL, bypass INTEGER NOT NULL DEFAULT 0, collapsed INTEGER NOT NULL DEFAULT 0);  -- bypass/collapsed: DO migration 3
CREATE TABLE edges (id TEXT PRIMARY KEY, canvas_id TEXT NOT NULL, from_node TEXT NOT NULL, from_port TEXT NOT NULL, to_node TEXT NOT NULL, to_port TEXT NOT NULL, ord INTEGER NOT NULL DEFAULT 0, pinned_version_id TEXT, reroutes TEXT);  -- reroutes: JSON [{x,y}] (DO migration 4)
CREATE TABLE node_versions (id TEXT PRIMARY KEY, node_id TEXT NOT NULL, n INTEGER NOT NULL, asset_id TEXT, output TEXT, input_digest TEXT NOT NULL, model TEXT, job_id TEXT, created_at INTEGER NOT NULL, rating TEXT, UNIQUE (node_id, n));  -- rating: D-005 safe/suggestive/explicit from the generation postCheck (DO migration 5)
CREATE TABLE groups (id TEXT PRIMARY KEY, canvas_id TEXT NOT NULL, title TEXT NOT NULL, color TEXT);
CREATE TABLE timelines (canvas_id TEXT PRIMARY KEY, edl TEXT NOT NULL, revision INTEGER NOT NULL);
CREATE TABLE patch_log (revision INTEGER PRIMARY KEY, actor TEXT NOT NULL, ops TEXT NOT NULL, created_at INTEGER NOT NULL, kind TEXT NOT NULL DEFAULT 'patch' CHECK (kind IN ('patch','undo','redo')), inverse TEXT NOT NULL DEFAULT '[]', target INTEGER, undone INTEGER NOT NULL DEFAULT 0);  -- undo/redo and audit (DO migration 2 adds kind/inverse/target/undone)
CREATE TABLE hub_subscribers (user_id TEXT PRIMARY KEY, subscribed_at INTEGER NOT NULL);  -- D-014: UserHub gateways subscribed to this project (DO migration 6)
CREATE TABLE event_ring (seq INTEGER PRIMARY KEY, revision INTEGER NOT NULL, type TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL);  -- D-014: newest 500 replayable events for resubscribe catch-up (DO migration 6)
CREATE TABLE agent_threads (thread_id TEXT PRIMARY KEY, caller TEXT NOT NULL, registered_at INTEGER NOT NULL);  -- agent threads bound to this project, notified on new revisions (DO migration 6)
-- D-031 collaboration: own migration chain `_migrations_collab` (packages/db/src/do/projectCollab.ts). Presence is memory only.
CREATE TABLE comment_threads (id TEXT PRIMARY KEY, anchor_kind TEXT NOT NULL CHECK (anchor_kind IN ('node','version','timeline','canvas','review')), anchor TEXT NOT NULL, node_id TEXT, status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','resolved')), review_id TEXT, created_by_kind TEXT NOT NULL, created_by TEXT NOT NULL, created_by_name TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, resolved_by TEXT, resolved_at INTEGER);
CREATE TABLE comments (id TEXT PRIMARY KEY, thread_id TEXT NOT NULL, author_kind TEXT NOT NULL CHECK (author_kind IN ('member','reviewer')), author_id TEXT NOT NULL, author_name TEXT NOT NULL, body TEXT NOT NULL, mentions TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, edited_at INTEGER, deleted_at INTEGER);
CREATE TABLE comment_reads (user_id TEXT NOT NULL, thread_id TEXT NOT NULL, read_at INTEGER NOT NULL, PRIMARY KEY (user_id, thread_id));  -- unread state
CREATE TABLE activity (id TEXT PRIMARY KEY, kind TEXT NOT NULL, actor_kind TEXT NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT, data TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);  -- project activity feed (newest 2,000)
-- DO migration 7 (D-021): who made each revision and, for Auto mode changes, the agent turn.
ALTER TABLE patch_log ADD COLUMN origin TEXT NOT NULL DEFAULT 'user';
ALTER TABLE patch_log ADD COLUMN source TEXT;
